-- Bistrô Teste (empresa virtual): migração simulada de um cliente real. Pratos,
-- categorias e preços vêm do cardápio QR público de um restaurante de frutos do mar
-- de Fortaleza (lido em 17/11/2026); descrições e fichas (alergênicos, dietas) são da
-- Tipe. Fotos: prato inteiro com a mesa, licença Unsplash (fontes em
-- public/cardapio/bistro/real/FONTES.md), cada uma com mapa de profundidade.
-- Bebidas de marca (0085/0086) continuam; só a cozinha é trocada.
do $$
declare rid uuid;
begin
  select id into rid from public.restaurants where slug = 'bistro-teste';
  if rid is null then return; end if;

  delete from public.pdv_menu_items i using public.pdv_menu_categories c
  where i.category_id = c.id and i.restaurant_id = rid
    and c.name in ('Entradas', 'Saladas', 'Principais', 'Acompanhamentos', 'Sobremesas');
  delete from public.pdv_menu_categories
  where restaurant_id = rid and name in ('Entradas', 'Saladas', 'Principais', 'Acompanhamentos', 'Sobremesas');

  insert into public.pdv_menu_categories (restaurant_id, name, position)
  select rid, c.name, c.pos
  from (values
    ('Entradas', 0), ('Saladas', 20), ('Camarões', 30), ('Peixes e frutos do mar', 35), ('Carnes e aves', 40), ('Pratos individuais', 45), ('Kids', 50), ('Sobremesas', 60)
  ) as c(name, pos)
  where not exists (select 1 from public.pdv_menu_categories x where x.restaurant_id = rid and x.name = c.name);

  insert into public.pdv_menu_items
    (restaurant_id, category_id, code, name, description, price, sector, position, available,
     image_url, depth_url, model_url, badge, allergens, menu_config)
  select rid, cat.id, i.code, i.name, i.description, i.price, 'kitchen', i.pos, true,
         i.image_url, i.depth_url, null, i.badge, i.allergens, i.config::jsonb
  from (values
    ('Entradas', 'BT-CARPACCIO', 'Carpaccio de filé', 'Lâminas finas de filé mignon com alcaparras, lascas de parmesão, rúcula e molho de mostarda.', 100.00, 1, 'https://tipe.digital/cardapio/bistro/real/carpaccio.webp', 'https://tipe.digital/cardapio/bistro/real/carpaccio-depth.png', null, array['leite', 'mostarda']::text[], '{"diets": ["gluten_free"]}'),
    ('Entradas', 'BT-CEVICHE', 'Ceviche de salmão', 'Salmão fresco em cubos marinado no limão, com cebola roxa, pimenta dedo-de-moça e coentro.', 88.00, 2, 'https://tipe.digital/cardapio/bistro/real/ceviche.webp', 'https://tipe.digital/cardapio/bistro/real/ceviche-depth.png', null, array['peixe']::text[], '{"diets": ["gluten_free", "lactose_free"]}'),
    ('Entradas', 'BT-POLVO', 'Polvo ao azeite com tomate seco', 'Polvo macio grelhado e regado no azeite com alho, tomate seco e batatas ao murro.', 136.00, 3, 'https://tipe.digital/cardapio/bistro/real/polvo.webp', 'https://tipe.digital/cardapio/bistro/real/polvo-depth.png', null, array['moluscos']::text[], '{"diets": ["gluten_free", "lactose_free"]}'),
    ('Entradas', 'BT-CAMALHO', 'Camarão no alho e óleo', 'Camarões salteados no azeite com alho dourado e salsinha, servidos na frigideira.', 68.00, 4, 'https://tipe.digital/cardapio/bistro/real/camalho.webp', 'https://tipe.digital/cardapio/bistro/real/camalho-depth.png', null, array['crustáceos']::text[], '{"diets": ["gluten_free", "lactose_free"], "featured": true, "recommendations": ["BT-HEINEKEN", "BT-CAIPI"]}'),
    ('Entradas', 'BT-LULA', 'Lula à dorê', 'Anéis de lula empanados e fritos na hora, com molho tártaro e limão.', 62.00, 5, 'https://tipe.digital/cardapio/bistro/real/lula.webp', 'https://tipe.digital/cardapio/bistro/real/lula-depth.png', null, array['moluscos', 'glúten', 'ovo', 'leite']::text[], '{"diets": [], "recommendations": ["BT-CORONA"]}'),
    ('Entradas', 'BT-ISCA', 'Isca de peixe', 'Tiras de peixe branco empanadas e crocantes, com molho tártaro e limão.', 79.00, 6, 'https://tipe.digital/cardapio/bistro/real/isca.webp', 'https://tipe.digital/cardapio/bistro/real/isca-depth.png', null, array['peixe', 'glúten', 'ovo', 'leite']::text[], '{"diets": [], "recommendations": ["BT-STELLA"]}'),
    ('Entradas', 'BT-CASQUINHA', 'Casquinha de caranguejo', 'Carne de caranguejo refogada no leite de coco e coentro, gratinada com farofa na manteiga.', 71.00, 7, 'https://tipe.digital/cardapio/bistro/real/casquinha.webp', 'https://tipe.digital/cardapio/bistro/real/casquinha-depth.png', null, array['crustáceos', 'leite']::text[], '{"diets": []}'),
    ('Entradas', 'BT-DADINHO', 'Dadinho de tapioca', 'Cubos de tapioca com queijo coalho, dourados e servidos com geleia de pimenta.', 66.00, 8, 'https://tipe.digital/cardapio/bistro/real/dadinho.webp', 'https://tipe.digital/cardapio/bistro/real/dadinho-depth.png', null, array['leite']::text[], '{"diets": ["vegetarian", "gluten_free"]}'),
    ('Entradas', 'BT-PASTEL', 'Pastel de carne de sol', 'Pastel crocante recheado com carne de sol desfiada e queijo coalho.', 46.00, 9, 'https://tipe.digital/cardapio/bistro/real/pastel.webp', 'https://tipe.digital/cardapio/bistro/real/pastel-depth.png', null, array['glúten', 'leite']::text[], '{"diets": []}'),
    ('Entradas', 'BT-CALDINHO', 'Caldinho de camarão', 'Caldo cremoso de camarão com leite de coco e cheiro-verde, servido bem quente.', 21.00, 10, 'https://tipe.digital/cardapio/bistro/real/caldinho.webp', 'https://tipe.digital/cardapio/bistro/real/caldinho-depth.png', null, array['crustáceos']::text[], '{"diets": ["gluten_free"]}'),
    ('Saladas', 'BT-CAESAR', 'Salada Caesar', 'Alface-romana, croutons, lascas de parmesão e molho Caesar da casa.', 44.00, 1, 'https://tipe.digital/cardapio/bistro/real/caesar.webp', 'https://tipe.digital/cardapio/bistro/real/caesar-depth.png', null, array['glúten', 'leite', 'ovo', 'peixe']::text[], '{"diets": ["vegetarian"]}'),
    ('Saladas', 'BT-TROPICAL', 'Salada tropical', 'Mix de folhas com manga, abacate, castanha de caju e vinagrete de maracujá.', 65.00, 2, 'https://tipe.digital/cardapio/bistro/real/tropical.webp', 'https://tipe.digital/cardapio/bistro/real/tropical-depth.png', null, array['castanhas']::text[], '{"diets": ["vegan", "vegetarian", "gluten_free", "lactose_free"]}'),
    ('Camarões', 'BT-INTERNAC', 'Camarão internacional', 'Arroz cremoso com camarões, presunto, ervilha e molho branco, gratinado com queijo. Serve 2 pessoas.', 176.00, 1, 'https://tipe.digital/cardapio/bistro/real/internacional.webp', 'https://tipe.digital/cardapio/bistro/real/internacional-depth.png', null, array['crustáceos', 'leite', 'glúten']::text[], '{"diets": [], "featured": true, "recommendations": ["BT-VINHO-B"]}'),
    ('Camarões', 'BT-CAMCOCO', 'Camarão ao leite de coco', 'Camarões ao molho de leite de coco, tomate e coentro, com arroz branco e farofa. Serve 2 pessoas.', 176.00, 2, 'https://tipe.digital/cardapio/bistro/real/mucuripe.webp', 'https://tipe.digital/cardapio/bistro/real/mucuripe-depth.png', null, array['crustáceos']::text[], '{"diets": ["gluten_free"], "recommendations": ["BT-VINHO-B"]}'),
    ('Camarões', 'BT-CAMGRELHA', 'Camarão grelhado', 'Camarões grandes grelhados na manteiga de ervas, com legumes salteados e limão.', 99.00, 3, 'https://tipe.digital/cardapio/bistro/real/grelhado.webp', 'https://tipe.digital/cardapio/bistro/real/grelhado-depth.png', null, array['crustáceos', 'leite']::text[], '{"diets": ["gluten_free"]}'),
    ('Camarões', 'BT-SCAMPI', 'Camarão scampi', 'Massa com camarões salteados na manteiga, alho, vinho branco e limão. Serve 2 pessoas.', 152.00, 4, 'https://tipe.digital/cardapio/bistro/real/scampi.webp', 'https://tipe.digital/cardapio/bistro/real/scampi-depth.png', null, array['crustáceos', 'glúten', 'leite', 'sulfitos']::text[], '{"diets": [], "recommendations": ["BT-VINHO-B"]}'),
    ('Peixes e frutos do mar', 'BT-MOQUECA', 'Moqueca cearense mista', 'Peixe, camarão e lula no leite de coco com pimentões e coentro, com arroz e pirão. Serve 2 pessoas.', 233.00, 1, 'https://tipe.digital/cardapio/bistro/real/moqueca.webp', 'https://tipe.digital/cardapio/bistro/real/moqueca-depth.png', 'Mais pedido', array['peixe', 'crustáceos', 'moluscos']::text[], '{"diets": ["gluten_free", "lactose_free"], "featured": true, "recommendations": ["BT-VINHO-B", "BT-CAIPI"]}'),
    ('Peixes e frutos do mar', 'BT-PESCADA', 'Pescada amarela à meunière', 'Filé de pescada amarela dourado na manteiga com alcaparras e limão, com arroz e batatas. Serve 2 pessoas.', 210.00, 2, 'https://tipe.digital/cardapio/bistro/real/pescada.webp', 'https://tipe.digital/cardapio/bistro/real/pescada-depth.png', null, array['peixe', 'leite', 'glúten']::text[], '{"diets": [], "recommendations": ["BT-VINHO-B"]}'),
    ('Peixes e frutos do mar', 'BT-BACALHAU', 'Bacalhau à Gomes de Sá', 'Lascas de bacalhau com batatas, cebola, ovos cozidos e azeitonas, assados no azeite. Serve 2 pessoas.', 149.00, 3, 'https://tipe.digital/cardapio/bistro/real/bacalhau.webp', 'https://tipe.digital/cardapio/bistro/real/bacalhau-depth.png', null, array['peixe', 'ovo']::text[], '{"diets": ["gluten_free", "lactose_free"], "recommendations": ["BT-VINHO-T"]}'),
    ('Peixes e frutos do mar', 'BT-TILAPIA', 'Tilápia grelhada', 'Filé de tilápia grelhado com legumes na chapa e limão.', 92.00, 4, 'https://tipe.digital/cardapio/bistro/real/tilapia.webp', 'https://tipe.digital/cardapio/bistro/real/tilapia-depth.png', null, array['peixe']::text[], '{"diets": ["gluten_free", "lactose_free"]}'),
    ('Peixes e frutos do mar', 'BT-PAELLA', 'Paella caldosa de frutos do mar', 'Arroz caldoso com camarão, lula, mexilhão e açafrão, servido na paellera. Serve 2 pessoas.', 220.00, 5, 'https://tipe.digital/cardapio/bistro/real/paella.webp', 'https://tipe.digital/cardapio/bistro/real/paella-depth.png', null, array['crustáceos', 'moluscos']::text[], '{"diets": ["gluten_free", "lactose_free"], "recommendations": ["BT-VINHO-B"]}'),
    ('Peixes e frutos do mar', 'BT-LAGOSTA', 'Lagosta grelhada', 'Lagosta grelhada na manteiga de alho, com legumes e molhos da casa. Serve 2 pessoas.', 290.00, 6, 'https://tipe.digital/cardapio/bistro/real/lagosta.webp', 'https://tipe.digital/cardapio/bistro/real/lagosta-depth.png', null, array['crustáceos', 'leite']::text[], '{"diets": ["gluten_free"], "recommendations": ["BT-VINHO-B"]}'),
    ('Carnes e aves', 'BT-PARMEGIA', 'Filé à parmegiana', 'Filé mignon empanado com molho de tomate e queijo gratinado, com arroz e fritas. Serve 2 pessoas.', 204.00, 1, 'https://tipe.digital/cardapio/bistro/real/parmegiana.webp', 'https://tipe.digital/cardapio/bistro/real/parmegiana-depth.png', null, array['glúten', 'leite', 'ovo']::text[], '{"diets": [], "recommendations": ["BT-COCA"]}'),
    ('Carnes e aves', 'BT-MADEIRA', 'Filé ao molho madeira', 'Medalhão de filé mignon ao molho madeira com cogumelos, com arroz e batatas. Serve 2 pessoas.', 136.00, 2, 'https://tipe.digital/cardapio/bistro/real/madeira.webp', 'https://tipe.digital/cardapio/bistro/real/madeira-depth.png', null, array['leite', 'glúten', 'sulfitos']::text[], '{"diets": [], "recommendations": ["BT-VINHO-T"]}'),
    ('Carnes e aves', 'BT-PICANHA', 'Picanha na chapa', 'Picanha fatiada servida na chapa quente, com farofa, vinagrete e arroz. Serve 2 pessoas.', 194.00, 3, 'https://tipe.digital/cardapio/bistro/real/picanha.webp', 'https://tipe.digital/cardapio/bistro/real/picanha-depth.png', null, array['leite']::text[], '{"diets": ["gluten_free"], "recommendations": ["BT-VINHO-T", "BT-HEINEKEN"]}'),
    ('Carnes e aves', 'BT-CARNESOL', 'Carne de sol do sertão', 'Carne de sol na manteiga de garrafa com macaxeira, queijo coalho e baião de dois. Serve 2 pessoas.', 161.00, 4, 'https://tipe.digital/cardapio/bistro/real/carnesol.webp', 'https://tipe.digital/cardapio/bistro/real/carnesol-depth.png', null, array['leite']::text[], '{"diets": ["gluten_free"], "recommendations": ["BT-CAIPI"]}'),
    ('Carnes e aves', 'BT-FRANGO', 'Frango grelhado', 'Peito de frango grelhado com ervas, batatas na chapa e aspargos.', 83.00, 5, 'https://tipe.digital/cardapio/bistro/real/frango.webp', 'https://tipe.digital/cardapio/bistro/real/frango-depth.png', null, array[]::text[], '{"diets": ["gluten_free", "lactose_free"]}'),
    ('Pratos individuais', 'BT-IND-CAMAR', 'Camarão grelhado individual', 'Camarões grelhados com limão e ervas, arroz e salada. Prato para 1 pessoa.', 72.90, 1, 'https://tipe.digital/cardapio/bistro/real/individual.webp', 'https://tipe.digital/cardapio/bistro/real/individual-depth.png', null, array['crustáceos']::text[], '{"diets": ["gluten_free", "lactose_free"]}'),
    ('Pratos individuais', 'BT-IND-SOL', 'Carne de sol individual', 'Carne de sol acebolada com arroz, feijão, farofa e ovo frito. Prato para 1 pessoa.', 65.90, 2, 'https://tipe.digital/cardapio/bistro/real/carnesol1.webp', 'https://tipe.digital/cardapio/bistro/real/carnesol1-depth.png', null, array['ovo', 'leite']::text[], '{"diets": ["gluten_free"]}'),
    ('Pratos individuais', 'BT-ESPAGUETE', 'Espaguete ao sugo', 'Espaguete com molho de tomate fresco, alho, azeite e manjericão. Prato para 1 pessoa.', 63.00, 3, 'https://tipe.digital/cardapio/bistro/real/espaguete.webp', 'https://tipe.digital/cardapio/bistro/real/espaguete-depth.png', null, array['glúten']::text[], '{"diets": ["vegan", "vegetarian", "lactose_free"]}'),
    ('Kids', 'BT-KIDS', 'Kids frango', 'Iscas de frango empanadas com batata frita. Prato infantil.', 48.00, 1, 'https://tipe.digital/cardapio/bistro/real/kids.webp', 'https://tipe.digital/cardapio/bistro/real/kids-depth.png', null, array['glúten', 'ovo', 'leite']::text[], '{"diets": []}'),
    ('Sobremesas', 'BT-LIMAO', 'Torta de limão', 'Fatia de torta com creme de limão sobre massa amanteigada e rodela de limão.', 35.00, 1, 'https://tipe.digital/cardapio/bistro/real/limao.webp', 'https://tipe.digital/cardapio/bistro/real/limao-depth.png', null, array['glúten', 'leite', 'ovo']::text[], '{"diets": ["vegetarian"]}'),
    ('Sobremesas', 'BT-PUDIM', 'Pudim de leite', 'Pudim de leite condensado, liso e cremoso, com calda de caramelo.', 34.00, 2, 'https://tipe.digital/cardapio/bistro/real/pudim.webp', 'https://tipe.digital/cardapio/bistro/real/pudim-depth.png', 'Mais pedido', array['leite', 'ovo']::text[], '{"diets": ["vegetarian", "gluten_free"], "recommendations": ["BT-CAFE"]}'),
    ('Sobremesas', 'BT-COCADA', 'Cocada de forno', 'Cocada cremosa assada com coco fresco e lascas de coco tostado.', 34.00, 3, 'https://tipe.digital/cardapio/bistro/real/cocada.webp', 'https://tipe.digital/cardapio/bistro/real/cocada-depth.png', null, array['leite', 'ovo']::text[], '{"diets": ["vegetarian", "gluten_free"], "recommendations": ["BT-CAFE"]}'),
    ('Sobremesas', 'BT-PETIT', 'Petit gâteau', 'Bolinho de chocolate com centro cremoso, servido com sorvete e calda de chocolate.', 46.00, 4, 'https://tipe.digital/cardapio/bistro/real/petit.webp', 'https://tipe.digital/cardapio/bistro/real/petit-depth.png', null, array['glúten', 'leite', 'ovo']::text[], '{"diets": ["vegetarian"], "recommendations": ["BT-CAFE"]}'),
    ('Sobremesas', 'BT-CHURROS', 'Churros com doce de leite', 'Churros crocantes com açúcar e canela, com doce de leite para mergulhar.', 42.00, 5, 'https://tipe.digital/cardapio/bistro/real/churros.webp', 'https://tipe.digital/cardapio/bistro/real/churros-depth.png', null, array['glúten', 'leite', 'ovo']::text[], '{"diets": ["vegetarian"], "recommendations": ["BT-CAFE"]}')
  ) as i(category, code, name, description, price, pos, image_url, depth_url, badge, allergens, config)
  join public.pdv_menu_categories cat on cat.restaurant_id = rid and cat.name = i.category
  where not exists (select 1 from public.pdv_menu_items x where x.restaurant_id = rid and x.code = i.code);
end $$;
